import json, re
for step in [0,50,100]:
    with open(f'results/run100/val_generations/{step}.jsonl') as f:
        lines=f.readlines()
    def tail_number(out):
        # last number anywhere in last 300 chars that is not part of a date etc; use gsm8k flexible
        m=re.findall(r'(-?[0-9\.\,]+)', out[-300:])
        if not m: return None
        for s in reversed(m):
            if s.replace(',','').replace('.','')!='':
                return s.replace(',','').replace('\$','')
        return None
    def boxed(out):
        m=re.findall(r'boxed\{([^{}]+)\}', out)
        return m[-1].strip().replace(',','').replace('\$','') if m else None
    def hashnum(out):
        m=re.findall(r'####\s*(-?[0-9\.\,]+)', out[-300:])
        return m[-1].replace(',','').replace('\$','') if m else None
