    rows = [json.loads(l) for l in open(path)]
    n = len(rows)
    box_tot = box_exact = hash_tot = hash_exact = flex_exact = 0
    for r in rows:
        out = r['output']
        gt = norm_num(str(r['gts']))
        boxm = re.findall(r'\\boxed\{([^{}]*)\}', out)
        hashm = re.findall(r'####\s*(-?[0-9.,]+)', out)
